// `img` is the plasma at this pixel; `img_at(ctx)` samples it anywhere.
// `c` is this pixel: c.theta (angle), c.r01 (0 outer .. 1 inner), c.pos (x, y).
let n = snoise3(vec3f(c.pos * 3.0, G.time * 0.2));
let warped = ctx_transform(c, n * twist * 0.4, 1.0 + 0.15 * n, 0.0, 0.0);
let s = img_at(warped);
let tint = 0.6 + 0.4 * c.r01;
out = vec4f(s.rgb * tint, s.a);
